mapper.select:
SELECT o.id, o.order_no, o.merchant_id, o.plan_id, o.amount, o.status, o.expire_at, o.created_at, COALESCE(m.name, '') AS merchant_name, COALESCE(p.name, '') AS plan_name, '在线支付' AS pay_type FROM order_record o LEFT JOIN merchant m ON o.merchant_id = m.id LEFT JOIN plan p ON o.plan_id = p.id
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND o.merchant_id = #{merchantId}
AND o.status = #{status}
AND o.created_at >= CONCAT(#{startDate}, ' 00:00:00')
AND o.created_at <= CONCAT(#{endDate}, ' 23:59:59')
ORDER BY o.created_at DESC LIMIT #{limit}
